contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _rewardToken) public {
        require(c.owner() == address(this), "test must be owner");
        require(c.rewardData(_rewardToken).lastUpdateTime == 0, "token must be unknown");
        c.setRewardDistributor(address(this));
        bool ok;
        bytes memory reason;
        (ok, reason) = address(c).call(
            abi.encodeWithSelector(c.notifyRewardAmount.selector, _rewardToken, 1)
        );
        // The 'not distributor' revert string encodes to exactly 4 + 32 + 15 = 51 bytes.
        // Original: distributor was updated, so failure (if any) is 'unknown reward token' (56 bytes).
        // Mutant: distributor never changes, so the call reverts with 'not distributor' (51 bytes).
        assert(ok || reason.length != 51);
    }
    receive() external payable {}
}

